from fractions import Fraction
from typing import Any

from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer


def _frac_to_str(x: float, max_denominator: int = 12) -> str:
    """Convert a float fractional coordinate to a compact rational string."""
    # Keep values in [0, 1) for fractional coordinates.
    x = float(x) % 1.0
    # Snap very-near-boundary values.
    if abs(x - 1.0) < 1e-8 or abs(x) < 1e-8:
        return "0"
    frac = Fraction(x).limit_denominator(max_denominator)
    # Normalize values extremely close to 1 after rounding.
    if frac.numerator == frac.denominator:
        return "0"
    return str(frac)


def analyze_wyckoff_position_multiplicities_and_coordinates(filepath: str) -> dict[str, Any]:
    """Analyze Wyckoff multiplicities and representative coordinates from a CIF file.

    Returns
    -------
    dict
        {
            "wyckoff_multiplicity_dict": {letter: multiplicity, ...},
            "wyckoff_coordinates_dict": {letter: [x, y, z], ...}
        }
    """
    structure = Structure.from_file(filepath)
    analyzer = SpacegroupAnalyzer(structure, symprec=1e-3)
    dataset = analyzer.get_symmetry_dataset()

    wyckoffs = list(dataset["wyckoffs"])
    equivalent_atoms = list(dataset["equivalent_atoms"])

    groups: dict[str, list[int]] = {}
    for idx, letter in enumerate(wyckoffs):
        if letter not in groups:
            groups[letter] = []
        # Only use one representative index per equivalent-atom group for a letter.
        rep = int(equivalent_atoms[idx])
        if rep not in groups[letter]:
            groups[letter].append(rep)

    multiplicity_dict: dict[str, int] = {}
    coordinates_dict: dict[str, list[str]] = {}

    for letter in sorted(groups.keys()):
        reps = sorted(groups[letter])
        multiplicity_dict[letter] = sum(1 for w in wyckoffs if w == letter)
        coord = structure[reps[0]].frac_coords
        coordinates_dict[letter] = [_frac_to_str(c, max_denominator=12) for c in coord]

    return {
        "wyckoff_multiplicity_dict": multiplicity_dict,
        "wyckoff_coordinates_dict": coordinates_dict,
    }


if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python solution.py <cif-file>")
    print(analyze_wyckoff_position_multiplicities_and_coordinates(sys.argv[1]))
